import{_ as t,a0 as o,w as d,s as r,I as n,x as a,a1 as i,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"精通 Linux 的 ls 命令 | LCTT x X-CMD","titleTemplate":false,"description":"精通 Linux 的 ls 命令 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精通 Linux 的 ls 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精通 Linux 的 ls 命令 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190724 Master the Linux -ls- command","title":"精通 Linux 的 ls 命令","tag":"201907","desc":""},"relativePath":"201907/20190724 Master the Linux -ls- command.md","filePath":"[post].md"}'),c={name:"201907/20190724 Master the Linux -ls- command.md"};function h(g,s,b,u,k,f){const e=o("Link");return d(),r("div",null,[s[40]||(s[40]=n("h1",{id:"精通-linux-的-ls-命令",tabindex:"-1"},[a("精通 Linux 的 ls 命令 "),n("a",{class:"header-anchor",href:"#精通-linux-的-ls-命令","aria-label":"Permalink to “精通 Linux 的 ls 命令”"},"​")],-1)),s[41]||(s[41]=n("blockquote",null,[n("p",null,"Linux 的 ls 命令擁有數量驚人的選項，可以提供有關文件的重要信息。")],-1)),s[42]||(s[42]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/29/105754ii3874q2ww7lo882.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=n("code",null,"ls",-1)),s[2]||(s[2]=a(" 命令可以列出一個 ",-1)),i(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:l(()=>[...s[0]||(s[0]=[a("POSIX",-1)])]),_:1}),s[3]||(s[3]=a(" 系統上的文件。這是一個簡單的命令，但它經常被低估，不是它能做什麼（因為它確實只做了一件事），而是你該如何優化對它的使用。",-1))]),s[43]||(s[43]=p(`<p>要知道在最重要的 10 個終端命令中，這個簡單的 <code>ls</code> 命令可以排進前三，因為 <code>ls</code> 不會<em>只是</em>列出文件，它還會告訴你有關它們的重要信息。它會告訴你諸如擁有文件或目錄的人、每個文件修改的時間、甚至是什麼類型的文件。它的附帶功能能讓你瞭解你在哪裏、附近有些什麼，以及你可以用它們做什麼。</p><p>如果你對 <code>ls</code> 的體驗僅限於你的發行版在 <code>.bashrc</code> 中的別名，那麼你可能錯失了它。</p><h3 id="gnu-還是-bsd" tabindex="-1">GNU 還是 BSD？ <a class="header-anchor" href="#gnu-還是-bsd" aria-label="Permalink to “GNU 還是 BSD？”">​</a></h3><p>在瞭解 <code>ls</code> 的隱藏能力之前，你必須確定你正在運行哪個 <code>ls</code> 命令。有兩個最流行的版本：包含在 GNU coreutils 包中的 GNU 版本，以及 BSD 版本。如果你正在運行 Linux，那麼你很可能已經安裝了 GNU 版本的 <code>ls</code>（LCTT 譯註：幾乎可以完全確定）。如果你正在運行 BSD 或 MacOS，那麼你有的是 BSD 版本。本文會介紹它們的不同之處。</p><p>你可以使用 <code>--version</code> 選項找出你計算機上的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --version</span></span></code></pre></div><p>如果它返回有關 GNU coreutils 的信息，那麼你擁有的是 GNU 版本。如果它返回一個錯誤，你可能正在運行的是 BSD 版本（運行 <code>man ls | head</code> 以確定）。</p><p>你還應該調查你的發行版可能具有哪些預設選項。終端命令的自定義通常放在 <code>$HOME/.bashrc</code> 或 <code>$HOME/.bash_aliases</code> 或 <code>$HOME/.profile</code> 中，它們是通過將 <code>ls</code> 別名化為更復雜的 <code>ls</code> 命令來完成的。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ls=&#39;ls --color&#39;</span></span></code></pre></div><p>發行版提供的預設非常有用，但它們確實很難分辨出哪些是 <code>ls</code> 本身的特性，哪些是它的附加選項提供的。你要是想要運行 <code>ls</code> 命令本身而不是它的別名，你可以用反斜槓“轉義”命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ \\ls</span></span></code></pre></div><h3 id="分類" tabindex="-1">分類 <a class="header-anchor" href="#分類" aria-label="Permalink to “分類”">​</a></h3><p>單獨運行 <code>ls</code> 會以適合你終端的列數列出文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls ~/example</span></span>
<span class="line"><span>bunko        jdk-10.0.2</span></span>
<span class="line"><span>chapterize   otf2ttf.ff</span></span>
<span class="line"><span>despacer     overtar.sh</span></span>
<span class="line"><span>estimate.sh  pandoc-2.7.1</span></span>
<span class="line"><span>fop-2.3      safe_yaml</span></span>
<span class="line"><span>games        tt</span></span></code></pre></div><p>這是有用的信息，但所有這些文件看起來基本相同，沒有方便的圖標來快速表示出哪個是目錄、文本文件或圖像等等。</p><p>使用 <code>-F</code>（或 GNU 上的長選項 <code>--classify</code>）以在每個條目之後顯示標識文件類型的指示符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls ~/example</span></span>
<span class="line"><span>bunko         jdk-10.0.2/</span></span>
<span class="line"><span>chapterize*   otf2ttf.ff*</span></span>
<span class="line"><span>despacer*     overtar.sh*</span></span>
<span class="line"><span>estimate.sh   pandoc@</span></span>
<span class="line"><span>fop-2.3/      pandoc-2.7.1/</span></span>
<span class="line"><span>games/        tt*</span></span></code></pre></div><p>使用此選項，終端中列出的項目使用簡寫符號來按文件類型分類：</p>`,18)),n("ul",null,[s[23]||(s[23]=n("li",null,[a("斜槓（"),n("code",null,"/"),a("）表示目錄（或“文件夾”）。")],-1)),n("li",null,[s[5]||(s[5]=a("星號（",-1)),s[6]||(s[6]=n("code",null,"*",-1)),s[7]||(s[7]=a("）表示可執行文件。這包括二進制文件（編譯代碼）以及腳本（具有",-1)),i(e,{href:"https://opensource.com/article/19/6/understanding-linux-permissions"},{default:l(()=>[...s[4]||(s[4]=[a("可執行權限",-1)])]),_:1}),s[8]||(s[8]=a("的文本文件）。",-1))]),s[24]||(s[24]=p("<li>符號（<code>@</code>）表示符號鏈接（或“別名”）。</li><li>等號（<code>=</code>）表示套接字。</li><li>在 BSD 上，百分號（<code>%</code>）表示<ruby>塗改<rt>whiteout</rt></ruby>（某些文件系統上的文件刪除方法）。</li>",3)),n("li",null,[s[10]||(s[10]=a("在 GNU 上，尖括號（",-1)),s[11]||(s[11]=n("code",null,">",-1)),s[12]||(s[12]=a("）表示",-1)),s[13]||(s[13]=n("ruby",null,[a("門"),n("rt",null,"door")],-1)),s[14]||(s[14]=a("（",-1)),i(e,{href:"https://www.illumos.org/"},{default:l(()=>[...s[9]||(s[9]=[a("Illumos",-1)])]),_:1}),s[15]||(s[15]=a(" 和 Solaris上的進程間通信）。",-1))]),n("li",null,[s[17]||(s[17]=a("豎線（",-1)),s[18]||(s[18]=n("code",null,"|",-1)),s[19]||(s[19]=a("）表示 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/FIFO_(computing_and_electronics)"},{default:l(()=>[...s[16]||(s[16]=[a("FIFO",-1)])]),_:1}),s[20]||(s[20]=a(" 管道。    這個選項的一個更簡單的版本是 ",-1)),s[21]||(s[21]=n("code",null,"-p",-1)),s[22]||(s[22]=a("，它只區分文件和目錄。",-1))])]),s[44]||(s[44]=p(`<p>（LCTT 譯註：在支持彩色的終端上，使用 <code>--color</code> 選項可以以不同的顏色來區分文件類型，但要注意如果將輸出導入到管道中，則顏色消失。）</p><h3 id="長列表" tabindex="-1">長列表 <a class="header-anchor" href="#長列表" aria-label="Permalink to “長列表”">​</a></h3><p>從 <code>ls</code> 獲取“長列表”的做法是如此常見，以至於許多發行版將 <code>ll</code> 別名為 <code>ls -l</code>。長列表提供了許多重要的文件屬性，例如權限、擁有每個文件的用户、文件所屬的組、文件大小（以字節為單位）以及文件上次更改的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users         455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users         662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    20697793 Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users        6210 May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users         177 Nov 12  2018 html4mutt.sh</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>如果你不想以字節為單位，請添加 <code>-h</code> 標誌（或 GNU 中的 <code>--human</code>）以將文件大小轉換為更加人性化的表示方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --human</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth seth     662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    20M Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth seth    6.1K May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    177 Nov 12  2018 html4mutt.sh</span></span></code></pre></div><p>要看到更少的信息，你可以帶有 <code>-o</code> 選項只顯示所有者的列，或帶有 <code>-g</code> 選項只顯示所屬組的列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -o</span></span>
<span class="line"><span>-rwxrwx---. 1 seth    455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth    662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth    20M Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth   6.1K May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth    177 Nov 12  2018 html4mutt.sh</span></span></code></pre></div><p>也可以將兩個選項組合使用以顯示兩者。</p><h3 id="時間和日期格式" tabindex="-1">時間和日期格式 <a class="header-anchor" href="#時間和日期格式" aria-label="Permalink to “時間和日期格式”">​</a></h3><p><code>ls</code> 的長列表格式通常如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rwxrwx---. 1 seth users         455 Mar  2  2017 estimate.sh</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users         662 Apr 29 22:27 factorial</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users    20697793 Jun 29  2018 fop-2.3-bin.tar.gz</span></span>
<span class="line"><span>-rwxrwxr-x. 1 seth users        6210 May 22 10:22 geteltorito</span></span>
<span class="line"><span>-rwxrwx---. 1 seth users         177 Nov 12  2018 html4mutt.sh</span></span></code></pre></div><p>月份的名字不便於排序，無論是通過計算還是識別（取決於你的大腦是否傾向於喜歡字符串或整數）。你可以使用 <code>--time-style</code> 選項和格式名稱更改時間戳的格式。可用格式為：</p><ul><li><code>full-iso</code>：ISO 完整格式（1970-01-01 21:12:00）</li><li><code>long-iso</code>：ISO 長格式（1970-01-01 21:12）</li><li><code>iso</code>：iso 格式（01-01 21:12）</li><li><code>locale</code>：本地化格式（使用你的區域設置）</li><li><code>posix-STYLE</code>：POSIX 風格（用區域設置定義替換 <code>STYLE</code>）</li></ul><p>你還可以使用 <code>date</code> 命令的正式表示法創建自定義樣式。</p><h3 id="按時間排序" tabindex="-1">按時間排序 <a class="header-anchor" href="#按時間排序" aria-label="Permalink to “按時間排序”">​</a></h3><p>通常，<code>ls</code> 命令按字母順序排序。你可以使用 <code>-t</code> 選項根據文件的最近更改的時間（最新的文件最先列出）進行排序。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch foo bar baz</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>bar  baz  foo</span></span>
<span class="line"><span>$ touch foo</span></span>
<span class="line"><span>$ ls -t</span></span>
<span class="line"><span>foo bar baz</span></span></code></pre></div><h3 id="列出方式" tabindex="-1">列出方式 <a class="header-anchor" href="#列出方式" aria-label="Permalink to “列出方式”">​</a></h3><p><code>ls</code> 的標準輸出平衡了可讀性和空間效率，但有時你需要按照特定方式排列的文件列表。</p><p>要以逗號分隔文件列表，請使用 <code>-m</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -m ~/example</span></span>
<span class="line"><span>bar, baz, foo</span></span></code></pre></div><p>要強制每行一個文件，請使用 <code>-1</code> 選項（這是數字 1，而不是小寫的 L）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 ~/bin/</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>baz</span></span>
<span class="line"><span>foo</span></span></code></pre></div><p>要按文件擴展名而不是文件名對條目進行排序，請使用 <code>-X</code>（這是大寫 X）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc</span></span>
<span class="line"><span>$ ls -X</span></span>
<span class="line"><span>foo.asc  baz.txt  bar.xfc</span></span></code></pre></div><h3 id="隱藏雜項" tabindex="-1">隱藏雜項 <a class="header-anchor" href="#隱藏雜項" aria-label="Permalink to “隱藏雜項”">​</a></h3><p>在某些 <code>ls</code> 列表中有一些你可能不關心的條目。例如，元字符 <code>.</code> 和 <code>..</code> 分別代表“本目錄”和“父目錄”。如果你熟悉在終端中如何切換目錄，你可能已經知道每個目錄都將自己稱為 <code>.</code>，並將其父目錄稱為 <code>..</code>，因此當你使用 <code>-a</code> 選項顯示隱藏文件時並不需要它經常提醒你。</p><p>要顯示幾乎所有隱藏文件（<code>.</code> 和 <code>..</code> 除外），請使用 <code>-A</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>..</span></span>
<span class="line"><span>.android</span></span>
<span class="line"><span>.atom</span></span>
<span class="line"><span>.bash_aliases</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>$ ls -A</span></span>
<span class="line"><span>.android</span></span>
<span class="line"><span>.atom</span></span>
<span class="line"><span>.bash_aliases</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>有許多優秀的 Unix 工具有保存備份文件的傳統，它們會在保存文件的名稱後附加一些特殊字符作為備份文件。例如，在 Vim 中，備份會以在文件名後附加 <code>~</code> 字符的文件名保存。</p><p>這些類型的備份文件已經多次使我免於愚蠢的錯誤，但是經過多年享受它們提供的安全感後，我覺得不需要用視覺證據來證明它們存在。我相信 Linux 應用程序可以生成備份文件（如果它們聲稱這樣做的話），我很樂意相信它們存在 —— 而不用必須看到它們。</p><p>要隱藏備份文件，請使用 <code>-B</code> 或 <code>--ignore-backups</code> 隱藏常用備份格式（此選項在 BSD 的 <code>ls</code> 中不可用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc~  foo.asc</span></span>
<span class="line"><span>$ ls -B</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc</span></span></code></pre></div><p>當然，備份文件仍然存在；它只是過濾掉了，你不必看到它。</p><p>除非另有配置，GNU Emacs 在文件名的開頭和結尾添加哈希字符（<code>＃</code>）來保存備份文件（<code>#file＃</code>）。其他應用程序可能使用不同的樣式。使用什麼模式並不重要，因為你可以使用 <code>--hide</code> 選項創建自己的排除項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar.xfc  baz.txt  #foo.asc#  foo.asc</span></span>
<span class="line"><span>$ ls --hide=&quot;#*#&quot;</span></span>
<span class="line"><span>bar.xfc  baz.txt  foo.asc</span></span></code></pre></div><h3 id="遞歸地列出目錄" tabindex="-1">遞歸地列出目錄 <a class="header-anchor" href="#遞歸地列出目錄" aria-label="Permalink to “遞歸地列出目錄”">​</a></h3><p>除非你在指定目錄上運行 <code>ls</code>，否則子目錄的內容不會與 <code>ls</code> 命令一起列出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -F</span></span>
<span class="line"><span>example/  quux*  xyz.txt</span></span>
<span class="line"><span>$ ls -R</span></span>
<span class="line"><span>quux  xyz.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>./example:</span></span>
<span class="line"><span>bar.xfc  baz.txt  #foo.asc#  foo.asc</span></span></code></pre></div><h3 id="使用別名使其永久化" tabindex="-1">使用別名使其永久化 <a class="header-anchor" href="#使用別名使其永久化" aria-label="Permalink to “使用別名使其永久化”">​</a></h3><p><code>ls</code> 命令可能是 shell 會話期間最常使用的命令。這是你的眼睛和耳朵，為你提供上下文信息和確認命令的結果。雖然有很多選項很有用，但 <code>ls</code> 之美的一部分就是簡潔：兩個字符和回車鍵，你就知道你到底在哪裏以及附近有什麼。如果你不得不停下思考（更不用説輸入）幾個不同的選項，它會變得不那麼方便，所以通常情況下，即使最有用的選項也不會用了。</p><p>解決方案是為你的 <code>ls</code> 命令添加別名，以便在使用它時，你可以獲得最關心的信息。</p><p>要在 Bash shell 中為命令創建別名，請在主目錄中創建名為 <code>.bash_aliases</code> 的文件（必須在開頭包含 <code>.</code>）。 在此文件中，列出要創建的別名，然後是要為其創建別名的命令。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ls=&#39;ls -A -F -B --human --color&#39;</span></span></code></pre></div><p>這一行導致你的 Bash shell 將 <code>ls</code> 命令解釋為 <code>ls -A -F -B --human --color</code>。</p><p>你不必僅限於重新定義現有命令，還可以創建自己的別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ll=&#39;ls -l&#39;</span></span>
<span class="line"><span>alias la=&#39;ls -A&#39;</span></span>
<span class="line"><span>alias lh=&#39;ls -h&#39;</span></span></code></pre></div><p>要使別名起作用，shell 必須知道 <code>.bash_aliases</code> 配置文件存在。在編輯器中打開 <code>.bashrc</code> 文件（如果它不存在則創建它），並包含以下代碼塊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -e $HOME/.bash_aliases ]; then</span></span>
<span class="line"><span>    source $HOME/.bash_aliases</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>每次加載 <code>.bashrc</code>（這是一個新的 Bash shell 啓動的時候），Bash 會將 <code>.bash_aliases</code> 加載到你的環境中。你可以關閉並重新啓動 Bash 會話，或者直接強制它執行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>如果你忘了你是否有別名命令，<code>which</code> 命令可以告訴你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which ls</span></span>
<span class="line"><span>alias ls=&#39;ls -A -F -B --human --color&#39;</span></span>
<span class="line"><span>        /usr/bin/ls</span></span></code></pre></div><p>如果你將 <code>ls</code> 命令別名為帶有選項的 <code>ls</code> 命令，則可以通過將反斜槓前綴到 <code>ls</code> 前來覆蓋你的別名。例如，在示例別名中，使用 <code>-B</code> 選項隱藏備份文件，這意味着無法使用 <code>ls</code> 命令顯示備份文件。 可以覆蓋該別名以查看備份文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>bar  baz  foo</span></span>
<span class="line"><span>$ \\ls</span></span>
<span class="line"><span>bar  baz  baz~  foo</span></span></code></pre></div><h3 id="做一件事-把它做好" tabindex="-1">做一件事，把它做好 <a class="header-anchor" href="#做一件事-把它做好" aria-label="Permalink to “做一件事，把它做好”">​</a></h3><p><code>ls</code> 命令有很多選項，其中許多是特定用途的或高度依賴於你所使用的終端。在 GNU 系統上查看 <code>info ls</code>，或在 GNU 或 BSD 系統上查看 <code>man ls</code> 以瞭解更多選項。</p><p>你可能會覺得奇怪的是，一個以每個工具“做一件事，把它做好”的前提而聞名的系統會讓其最常見的命令揹負 50 個選項。但是 <code>ls</code> 只做一件事：它列出文件，而這 50 個選項允許你控制接收列表的方式，<code>ls</code> 的這項工作做得非常、<em>非常</em>好。</p><hr>`,61)),n("p",null,[s[26]||(s[26]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/7/master-ls-command"},{default:l(()=>[...s[25]||(s[25]=[a("https://opensource.com/article/19/7/master-ls-command",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[27]||(s[27]=[a("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[28]||(s[28]=[a("lujun9972",-1)])]),_:1}),s[33]||(s[33]=a(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[29]||(s[29]=[a("wxy",-1)])]),_:1}),s[34]||(s[34]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[37]||(s[37]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[36]||(s[36]=[a("Linux中國",-1)])]),_:1}),s[39]||(s[39]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",h]]);export{y as __pageData,C as default};
